          const subtotal = items.reduce((sum, line) => sum + line.quantity * line.variant.price, 0);
          const pakistanDiscount = country === 'PK' ? Math.min(50, Math.max(0, subtotal - 2)) : 0;
          const localCurrency = checkoutCurrencies[country] || 'AED';
